// COOPERMAX — Motor de Enquadramento (servidor). Fonte oficial da apuração.
// Reaplica a matriz sobre o que o portal enviou: o front é conveniência, aqui é o registro.

const MATRIZ = {
  inflam:{t:"Inflamáveis ou combustíveis na área",enq:"PERIC",pct:30,base:"NR-16, Anexo 2",nat:"qual"},
  areacl:{t:"Área classificada / atmosfera explosiva",enq:"PERIC",pct:30,base:"NR-16, Anexo 2",nat:"qual"},
  quente:{t:"Serviço a quente",enq:null,pct:0,base:"—",nat:"qual"},
  explos:{t:"Explosivos",enq:"PERIC",pct:30,base:"NR-16, Anexo 1",nat:"qual"},
  eletri:{t:"Instalações elétricas energizadas ou SEP",enq:"PERIC",pct:30,base:"NR-16, Anexo 4",nat:"qual"},
  confin:{t:"Espaço confinado",enq:null,pct:0,base:"NR-33",nat:"qual"},
  altura:{t:"Trabalho em altura acima de 2 m",enq:null,pct:0,base:"NR-35",nat:"qual"},
  moto:{t:"Uso habitual de motocicleta no serviço",enq:"PERIC",pct:30,base:"NR-16, Anexo 5",nat:"qual"},
  segpat:{t:"Atividade de segurança patrimonial",enq:"PERIC",pct:30,base:"NR-16, Anexo 3",nat:"qual",obs:"Só enquadra se por empresa autorizada pelo Min. da Justiça."},
  radion:{t:"Radiação ionizante",enq:"PERIC",pct:30,base:"NR-16, Portaria 3.393/87",nat:"qual"},
  pacien:{t:"Contato com pacientes ou material biológico",enq:"INSAL",pct:20,base:"NR-15, Anexo 14",nat:"qual"},
  isolam:{t:"Paciente em isolamento infectocontagioso",enq:"INSAL",pct:40,base:"NR-15, Anexo 14",nat:"qual"},
  sanita:{t:"Limpeza de sanitário de uso público ou coletivo",enq:"INSAL",pct:40,base:"NR-15, Anexo 14 + Súmula 448 do TST",nat:"qual"},
  lixour:{t:"Coleta de lixo urbano",enq:"INSAL",pct:40,base:"NR-15, Anexo 14",nat:"qual"},
  esgoto:{t:"Esgoto — galerias, tanques, fossas",enq:"INSAL",pct:40,base:"NR-15, Anexo 14",nat:"qual"},
  calor:{t:"Calor — forno, caldeira, cozinha industrial",enq:"INSAL",pct:20,base:"NR-15, Anexo 3",nat:"quant"},
  frio:{t:"Frio — câmara fria",enq:"INSAL",pct:20,base:"NR-15, Anexo 9",nat:"qual"},
  umidad:{t:"Umidade — locais alagados",enq:"INSAL",pct:20,base:"NR-15, Anexo 10",nat:"qual"},
  ruido:{t:"Ruído elevado",enq:"INSAL",pct:20,base:"NR-15, Anexo 1",nat:"quant"},
  poeira:{t:"Poeira mineral — sílica, cimento, asbesto",enq:"INSAL",pct:40,base:"NR-15, Anexo 12",nat:"quant"},
  fumos:{t:"Fumos metálicos — soldagem",enq:"INSAL",pct:40,base:"NR-15, Anexo 12",nat:"quant",obs:"Manganês, limite 1 mg/m³. EPI não afasta."},
  uvsold:{t:"Radiação do arco de solda",enq:"INSAL",pct:20,base:"NR-15, Anexo 7",nat:"qual"},
  quimic:{t:"Produtos químicos",enq:"INSAL",pct:20,base:"NR-15, Anexos 11 e 13",nat:"quant"},
  vibrac:{t:"Vibração",enq:"INSAL",pct:20,base:"NR-15, Anexo 8",nat:"quant"},
  nenhum:{t:"Nenhuma condição",enq:null,pct:0,base:"—",nat:"qual"}
};

// efetivo e percentual praticado hoje (matriz de garantias, jun/2026)
const CARTEIRA = {
  "Soldador":{n:5,hoje:null},
  "Auxiliar de serviços gerais":{n:32,hoje:20},
  "Encarregado de serviços gerais":{n:1,hoje:20},
  "Auxiliar de serviços de alimentação":{n:44,hoje:20},
  "Cozinheiro":{n:3,hoje:null},
  "Auxiliar de padaria":{n:2,hoje:null},
  "Atendente de lanchonete":{n:4,hoje:0},
  "Técnico de enfermagem":{n:12,hoje:20},
  "Enfermeiro":{n:1,hoje:20},
  "Técnico de laboratório":{n:4,hoje:20},
  "Técnico de radiologia":{n:2,hoje:null},
  "Cuidador de idoso":{n:2,hoje:null},
  "Atendente de consultório":{n:6,hoje:20},
  "Recepcionista":{n:16,hoje:20},
  "Porteiro":{n:3,hoje:0},
  "Rondista":{n:2,hoje:null},
  "Auxiliar de manutenção predial":{n:1,hoje:null},
  "Pintor":{n:2,hoje:20},
  "Servente de obras":{n:17,hoje:null},
  "Pedreiro":{n:15,hoje:null},
  "Betoneiro":{n:2,hoje:null},
  "Carpinteiro":{n:5,hoje:null},
  "Armador":{n:5,hoje:null},
  "Motorista":{n:1,hoje:0}
};

// Central de atendimento POR PARCEIRA — a coordenação responde por todas as
// contratações daquela empresa, qualquer que seja a atividade.
const CENTRAL_PARCEIRA = {
  "petrox":  "obras",
  "gsi":     "saude",
  "uniclin": "saude"
};

// Usado apenas quando a solicitação não veio pelo link de uma parceira cadastrada.
const SEGMENTO = {
  "Soldador":"obras","Pedreiro":"obras","Servente de obras":"obras","Carpinteiro":"obras",
  "Armador":"obras","Pintor":"obras","Betoneiro":"obras","Auxiliar de manutenção predial":"obras",
  "Almoxarife":"obras","Mestre de obras":"obras","Auxiliar de serviços gerais":"obras",
  "Encarregado de serviços gerais":"obras","Porteiro":"obras","Rondista":"obras",
  "Recepcionista":"obras","Motorista":"obras","Auxiliar administrativo":"obras",
  "Operador de telemarketing":"obras","Analista de licitação":"obras",
  "Auxiliar de serviços de alimentação":"saude","Cozinheiro":"saude",
  "Atendente de lanchonete":"saude","Auxiliar de padaria":"saude",
  "Técnico de enfermagem":"saude","Enfermeiro":"saude","Técnico de laboratório":"saude",
  "Técnico de radiologia":"saude","Cuidador de idoso":"saude","Atendente de consultório":"saude"
};

const d = $input.first().json.body || $input.first().json;
const ids = Array.isArray(d.condicoes) ? d.condicoes : [];
const cfg = $('Configuração').first().json;

const area = CENTRAL_PARCEIRA[(d.parceira || "").toLowerCase()]
          || SEGMENTO[d.funcao]
          || "obras";
const central = area === "saude"
  ? { nome: "Saúde e Alimentação",     fone: cfg.centralSaude }
  : { nome: "Obras e Serviços Gerais", fone: cfg.centralObras };

const hits = ids.map(i => MATRIZ[i] ? Object.assign({id:i}, MATRIZ[i]) : null)
                .filter(x => x && x.enq)
                .sort((a,b) => b.pct - a.pct);

const aplicado  = hits.find(i => i.nat === "qual") || null;
const quant     = hits.filter(i => i.nat === "quant");
const potencial = quant.find(i => !aplicado || i.pct > aplicado.pct) || null;

const perfil = CARTEIRA[d.funcao] || null;
const alvo   = potencial ? potencial.pct : (aplicado ? aplicado.pct : 0);

let alerta = "SEM REFERÊNCIA", corAlerta = "#6B7477", acao = "Cargo fora da matriz de carteira. Cadastrar.";
if (perfil) {
  if (perfil.hoje === null) {
    alerta = "SEM DEFINIÇÃO NA CARTEIRA"; corAlerta = "#B26A00";
    acao = "A matriz registra este cargo como verificar. Levar esta apuração à Assembleia.";
  } else if (alvo > perfil.hoje) {
    alerta = "DIVERGÊNCIA — PAGANDO A MENOS"; corAlerta = "#B3261E";
    acao = "Carteira pratica " + (perfil.hoje === 0 ? "sem adicional" : perfil.hoje + "%")
         + " e a apuração indica " + alvo + "%. Auditar os " + perfil.n + " cooperados do cargo.";
  } else if (alvo < perfil.hoje) {
    alerta = "APURADO ABAIXO DO PRATICADO"; corAlerta = "#17727C";
    acao = "Não reduzir sem laudo — o mesmo cargo pode ter postos com exposições distintas.";
  } else {
    alerta = "CONFORME"; corAlerta = "#1B8A5A";
    acao = "A apuração confirma o percentual praticado na carteira.";
  }
}

const resumoTexto =
  "*COOPERMAX — Nova solicitação pelo Portal*\n" +
  "Central: " + central.nome + "\n" +
  "Protocolo: " + (d.protocolo || "—") + "\n" +
  "Contratante: " + (d.razao || "—") + "\n" +
  "Unidade: " + (d.unidade || "—") + "\n" +
  "Atividade: " + (d.funcao || "—") + " (" + (d.qtd || 1) + ")\n" +
  "Início: " + (d.inicio || "—") + "\n\n" +
  "*Enquadramento apurado*\n" +
  (aplicado
    ? (aplicado.enq === "PERIC" ? "Periculosidade " : "Insalubridade ") + aplicado.pct + "% — " + aplicado.base
    : "Sem enquadramento imediato") + "\n" +
  (potencial ? "Potencial: " + potencial.pct + "% (" + potencial.t + ") — exige medição\n" : "") +
  "\n*" + alerta + "*\n" + acao + "\n\n" +
  "Assinado por " + (d.assNome || "—") + " (" + (d.assCpf || "—") + ") em " + (d.dataHora || "—") +
  "\nVerificador: " + (d.verificador || "—");

return [{
  json: Object.assign({}, d, {
    apurado: {
      condicoes: hits,
      aplicado,
      potencial,
      alerta,
      corAlerta,
      acao,
      efetivoCargo: perfil ? perfil.n : null,
      praticadoHoje: perfil ? perfil.hoje : null,
      percentualFinal: aplicado ? aplicado.pct : 0,
      naturezaFinal: aplicado ? (aplicado.enq === "PERIC" ? "Periculosidade" : "Insalubridade") : "Sem adicional"
    },
    resumoTexto,
    central,
    recebidoEm: new Date().toISOString()
  })
}];

const d = $input.first().json;
const a = d.apurado;
const esc = s => String(s == null ? "—" : s).replace(/[<>&]/g, c => ({"<":"&lt;",">":"&gt;","&":"&amp;"}[c]));

const linha = (k, v) => "<tr><td class='k'>" + k + "</td><td>" + esc(v) + "</td></tr>";

const condicoes = (a.condicoes || []).map(c =>
  "<tr><td>" + esc(c.t) + "</td><td>" + esc(c.base) + "</td><td class='c'>" +
  (c.nat === "quant" ? "medição" : "inspeção") + "</td><td class='c b'>" +
  (c.enq === "PERIC" ? "Peric. " : "Insal. ") + c.pct + "%</td></tr>").join("");

const html = `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8">
<title>Protocolo ${esc(d.protocolo)} — COOPERMAX</title><style>
*{box-sizing:border-box}body{font:13px/1.5 Calibri,Arial,sans-serif;color:#2E3436;max-width:760px;margin:24px auto;padding:0 20px}
h1{font-size:19px;color:#17727C;margin-bottom:2px}h2{font-size:13px;color:#17727C;margin:20px 0 7px;
text-transform:uppercase;letter-spacing:.5px;border-bottom:2px solid #28B0BC;padding-bottom:4px}
.top{border-bottom:3px solid #28B0BC;padding-bottom:10px;margin-bottom:16px}
.sub{color:#6B7477;font-size:12px}
table{width:100%;border-collapse:collapse;margin-bottom:8px}
td,th{padding:6px 8px;border-bottom:1px solid #DCE3E4;vertical-align:top;font-size:12.5px}
th{background:#17727C;color:#fff;text-align:left;font-size:11.5px}
.k{color:#6B7477;font-weight:600;width:32%}
.c{text-align:center}.b{font-weight:700;color:#17727C;white-space:nowrap}
.box{border-left:4px solid #28B0BC;background:#FAFCFC;padding:10px 13px;margin:10px 0;font-size:12.5px}
.alerta{border-left:4px solid ${a.corAlerta};background:#FCFAFA;padding:10px 13px;margin:10px 0;font-size:12.5px}
.tag{display:inline-block;background:#E6F5F7;color:#17727C;border-radius:5px;padding:2px 7px;font-size:11.5px;margin:2px 3px 2px 0}
.rod{margin-top:22px;border-top:1px solid #DCE3E4;padding-top:8px;font-size:10.5px;color:#8A8A8A;font-style:italic}
@media print{body{margin:0}}
</style></head><body>
<div class="top"><h1>COOPERMAX — Protocolo de Solicitação de Atividade</h1>
<div class="sub">Cooperativa de Trabalho Multiprofissionais · Aracaju/SE · Protocolo ${esc(d.protocolo)}</div></div>

<h2>Contratante</h2><table>
${linha("Razão social", d.razao)}${linha("CNPJ", d.cnpj)}${linha("Unidade", d.unidade)}
${linha("Responsável", (d.resp || "") + " — " + (d.cargo || ""))}
${linha("Contato", (d.fone || "") + "  ·  " + (d.email || ""))}
${linha("RT de SST", d.rtsst)}</table>

<h2>Atividade solicitada</h2><table>
${linha("Função", d.funcao)}${linha("Cooperados", d.qtd)}${linha("Início previsto", d.inicio)}
${linha("Regime / escala", (d.regime || "") + " · " + (d.escala || "") + (d.horas ? " · " + d.horas + " h/mês" : ""))}
${linha("Descrição", d.descricao)}${linha("Qualificação exigida", d.qualif)}</table>

<h2>Condições declaradas pela contratante</h2>
<p>${(d.condNomes || []).map(n => "<span class='tag'>" + esc(n) + "</span>").join("")}</p>
${d.quimicos ? "<p><b>Agentes químicos:</b> " + esc(d.quimicos) + "</p>" : ""}
<table>${linha("Proteção coletiva", (d.epc || []).join(", "))}${linha("PGR / LTCAT", d.pgr)}
${linha("Laudo do posto", d.laudo)}${linha("Permissão de Trabalho", d.pt)}</table>

<h2>Apuração técnica COOPERMAX</h2>
<table><tr><th>Condição</th><th>Fundamento</th><th>Apuração</th><th>Grau</th></tr>${condicoes || "<tr><td colspan=4>Nenhuma condição geradora de enquadramento.</td></tr>"}</table>
<div class="box"><b>APLICAR: ${a.aplicado ? (a.aplicado.enq === "PERIC" ? "PERICULOSIDADE" : "INSALUBRIDADE") + " — " + a.aplicado.pct + "% sobre a retirada" : "sem adicional"}.</b>
${a.aplicado ? esc(a.aplicado.base) + ". Apuração qualitativa, aplicável de imediato." : "Nenhuma condição declarada gera adicional."}</div>
${a.potencial ? "<div class='box'><b>POTENCIAL DE ELEVAÇÃO: " + a.potencial.pct + "%</b> — " + esc(a.potencial.t) + " (" + esc(a.potencial.base) + "). Exige medição; se confirmada, prevalece por ser mais vantajosa ao cooperado. Manter cláusula de revisão em 30 dias.</div>" : ""}
<div class="alerta"><b>${esc(a.alerta)}.</b> ${esc(a.acao)}${a.efetivoCargo ? " Efetivo no cargo: " + a.efetivoCargo + " cooperado(s)." : ""}</div>

<h2>Aceite eletrônico</h2><table>
${linha("Assinado por", (d.assNome || "") + " — " + (d.cargo || ""))}${linha("CPF", d.assCpf)}
${linha("Data e hora", d.dataHora)}${linha("Código de verificação", d.verificador)}</table>
<div class="rod">Aceite eletrônico admitido como válido pelas partes nos termos do art. 10, §2º da MP nº 2.200-2/2001.
Adicionais não cumuláveis — prevalece o mais vantajoso ao cooperado. Base de cálculo: retirada do cooperado, art. 7º, VI da Lei nº 12.690/2012.
Percentual definitivo depende de laudo técnico e de deliberação em Assembleia Geral.</div>
</body></html>`;

return [{ json: { ...d, html }, binary: {} }];
